import sys, os
sys.path.insert(0, os.path.join(os.getcwd(), "src")); sys.path.insert(0, os.getcwd())
from tests import i18n_check as chk
T = {"en": {"Guvenlik tanimlayicilari yaziliyor ($Secure)...":
            "Writing security descriptors ($Secure)..."},
     "de": {"Guvenlik tanimlayicilari yaziliyor ($Secure)...":
            "Sicherheitsbeschreibungen werden geschrieben ($Secure) ..."}}
for code, table in T.items():
    cat = chk.load(code); n = 0
    for e in cat.entries:
        if not e.obsolete and e.plural is None and not e.translated:
            v = table.get(e.msgid)
            if v:
                e.msgstr = v; e.fuzzy = False; n += 1
            else:
                print("EKSIK", code, repr(e.msgid))
    chk.save(code, cat); print(code, n)
